#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/robotweax_srt/config.h>
// pydoc.h is automatically generated in the build directory
#include <config_pydoc.h>

void bind_config(py::module& m)
{
    using namespace gr::robotweax_srt;

    py::enum_<sample_format>(m, "sample_format")
        .value("f32", sample_format::f32)
        .value("cf32", sample_format::cf32);
    py::enum_<connection_role>(m, "connection_role")
        .value("caller", connection_role::caller)
        .value("listener", connection_role::listener);
    py::enum_<continuity_policy>(m, "continuity_policy")
        .value("strict_stop", continuity_policy::strict_stop)
        .value("segmented_live", continuity_policy::segmented_live);
    py::enum_<security_mode>(m, "security_mode")
        .value("none", security_mode::none)
        .value("ctr", security_mode::ctr);

    py::class_<transport_config>(m, "transport_config", D(transport_config))
        .def(py::init<>())
        .def_readwrite("role", &transport_config::role)
        .def_readwrite("host", &transport_config::host)
        .def_readwrite("bind_address", &transport_config::bind_address)
        .def_readwrite("port", &transport_config::port)
        .def_readwrite("stream_id", &transport_config::stream_id)
        .def_readwrite("latency_ms", &transport_config::latency_ms)
        .def_readwrite("connect_timeout_ms", &transport_config::connect_timeout_ms)
        .def_readwrite("startup_timeout_ms", &transport_config::startup_timeout_ms)
        .def_readwrite("reconnect", &transport_config::reconnect)
        .def_readwrite("reconnect_initial_ms", &transport_config::reconnect_initial_ms)
        .def_readwrite("reconnect_max_ms", &transport_config::reconnect_max_ms)
        .def_readwrite("reconnect_total_timeout_ms",
                       &transport_config::reconnect_total_timeout_ms)
        .def_readwrite("stop_timeout_ms", &transport_config::stop_timeout_ms)
        .def_readwrite("security", &transport_config::security)
        .def_readwrite("passphrase_env", &transport_config::passphrase_env)
        .def_readwrite("status_interval_ms", &transport_config::status_interval_ms);

    py::class_<stream_config>(m, "stream_config", D(stream_config))
        .def(py::init<>())
        .def_readwrite("format", &stream_config::format)
        .def_readwrite("sample_rate_num", &stream_config::sample_rate_num)
        .def_readwrite("sample_rate_den", &stream_config::sample_rate_den)
        .def_readwrite("record_limit_bytes", &stream_config::record_limit_bytes)
        .def_readwrite("flush_interval_ms", &stream_config::flush_interval_ms)
        .def_readwrite("queue_max_bytes", &stream_config::queue_max_bytes)
        .def_readwrite("queue_max_records", &stream_config::queue_max_records)
        .def_readwrite("queue_max_age_ms", &stream_config::queue_max_age_ms)
        .def_readwrite("continuity", &stream_config::continuity);
}
